// Regenerates ../index.d.ts — the declaration barrel lib/dts.mjs uses as its
// `entry`. Derived from cfg.componentSrcMap so the DTS component set is exactly
// the synced set; a bare `export *` would pull in every subcomponent (59, not
// 21). Run after the tsc declaration emit — see cfg.buildCmd.
import { readFileSync, writeFileSync } from "node:fs";

const cfg = JSON.parse(readFileSync(new URL("./config.json", import.meta.url), "utf8"));
const lines = [
  "// GENERATED by .design-sync/gen-dts-barrel.mjs — do not hand-edit.",
  "// Declaration barrel for lib/dts.mjs: gives it a resolvable `entry` so each",
  "// component's props come from the TS checker instead of an empty index",
  "// signature. Regenerate with cfg.buildCmd.",
  "",
];
for (const [name, src] of Object.entries(cfg.componentSrcMap)) {
  if (!src) continue;
  const path = "./dist/types/" + src.replace(/^src\//, "").replace(/\.tsx?$/, "");
  lines.push(`export { ${name} } from "${path}";`);
}
writeFileSync(new URL("../index.d.ts", import.meta.url), lines.join("\n") + "\n");
console.log(`index.d.ts: ${lines.length - 5} exports`);
